const items = $input.all();
const results = [];

for (const item of items) {
  try {
    const responseContent = item.json.choices[0].message.content;
    const parsed = JSON.parse(responseContent);

    results.push({
      json: {
        notes_original: item.json.notes_original || '',
        Hours: item.json.Hours || 0,
        states: item.json.states || [],
        category: parsed.category || 'No Comments / Not Specified',
        categorized_hours: parsed.hours || item.json.Hours || 0
      }
    });
  } catch (error) {
    // If parsing fails, mark as uncategorized
    results.push({
      json: {
        notes_original: item.json.notes_original || '',
        Hours: item.json.Hours || 0,
        states: item.json.states || [],
        category: 'No Comments / Not Specified',
        categorized_hours: item.json.Hours || 0,
        error: error.message
      }
    });
  }
}

return results;
